// src/pages/MeetingRoom.js

import {
  useLocation,
} from "react-router-dom";

import {
  useState,
  useEffect,
  useRef,
} from "react";

function MeetingRoom() {
  const location = useLocation();

  const roomTitle =
    location.state?.title ||
    "독서모임";

  const roomMood =
    location.state?.mood ||
    "badge1";

  const [input, setInput] =
    useState("");

  const [messages, setMessages] =
    useState([
      {
        user: "AI",
        type: "ai",
        text:
          "모임원들의 독후감과 기록을 먼저 정리했어요 ✨\n\n• 외로움과 연결감\n• 상실 이후의 성장\n• 잔잔하지만 깊은 감정선\n• 현실적인 인간 관계",
      },

      {
        user: "AI",
        type: "ai",
        text:
          "오늘은 가장 기억에 남았던 문장을 함께 이야기해볼게요 🙂",
      },

      {
        user: "민지",
        type: "other",
        color: "#FFB6C1",
        text:
          "저는 마지막 장면이 가장 슬펐어요.",
      },

      {
        user: "현우",
        type: "other",
        color: "#87CEEB",
        text:
          "문장이 진짜 고요해서 좋았어요.",
      },

      {
        user: "서연",
        type: "other",
        color: "#C3E88D",
        text:
          "와타나베 감정선이 너무 현실적이었어요.",
      },
    ]);

  const chatEndRef =
    useRef(null);

  // =========================
  // 새로운 메시지가 추가되면
  // 채팅창을 가장 아래로 이동
  // =========================

  useEffect(() => {
    chatEndRef.current?.scrollIntoView({
      behavior: "smooth",
      block: "nearest",
    });
  }, [messages]);

  // =========================
  // 일반 메시지 전송
  // =========================

  const sendMessage = () => {
    if (!input.trim()) {
      return;
    }

    const myMessage = {
      user: "나",
      type: "me",
      text: input.trim(),
    };

    setMessages((prev) => [
      ...prev,
      myMessage,
    ]);

    setInput("");

    /*
      중요

      여기에서는 AI가 자동으로
      답변하지 않는다.

      나중에 실제 백엔드 연결 시
      메시지를 백엔드로 보내는
      로직을 여기에 추가하면 된다.
    */
  };

  // =========================
  // AI 진행자 호출
  // =========================

  const requestAI = async () => {

    /*
      현재까지의 대화 내용

      나중에 이 데이터를
      백엔드로 그대로 전달할 예정
    */

    const conversation =
      messages.map((message) => ({
        user: message.user,
        type: message.type,
        text: message.text,
      }));

    const requestData = {
      roomTitle: roomTitle,
      mood: roomMood,
      messages: conversation,
    };

    console.log(
      "AI 요청 데이터:",
      requestData
    );

    /*
      ==================================
      나중에 백엔드 연결
      ==================================

      const response = await fetch(
        "http://localhost:8080/api/meeting/ai",
        {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
          },
          body: JSON.stringify(requestData),
        }
      );

      const data = await response.json();

      const aiReply = {
        user: "AI",
        type: "ai",
        text: data.message,
      };

      setMessages((prev) => [
        ...prev,
        aiReply,
      ]);

      ==================================
    */

    // 지금은 백엔드가 없으므로
    // 임시 AI 응답

    const aiReply = {
      user: "AI",
      type: "ai",
      text:
        "좋은 의견들이 나오고 있네요 🌿\n\n지금까지 이야기한 내용을 보면 인물의 감정과 상실에 대한 이야기가 많이 나온 것 같아요.\n\n여러분은 이 책에서 가장 공감했던 인물의 감정이 무엇이었나요?",
    };

    setMessages((prev) => [
      ...prev,
      aiReply,
    ]);
  };

  return (
    <div className="meeting-page">

      {/* =========================
          헤더
      ========================= */}

      <div className="meeting-header">

        <div>
          <div className="meeting-room-name">
            📚 {roomTitle}
          </div>
        </div>

      </div>


      {/* =========================
          채팅 영역
      ========================= */}

      <div className="meeting-chat-area">

        {messages.map((msg, index) => (

          <div
            key={index}
            className={`chat-row ${
              msg.type === "me"
                ? "right"
                : "left"
            }`}
          >

            {/* 프로필 */}

            {msg.type !== "me" && (

              <div
                className="chat-profile"
                style={{
                  background:
                    msg.type === "ai"
                      ? "#9bd44e"
                      : msg.color,
                }}
              >
                {msg.user[0]}
              </div>

            )}


            {/* 이름 + 말풍선 */}

            <div className="chat-content">

              {msg.type !== "me" && (

                <div className="chat-name">
                  {msg.user}
                </div>

              )}

              <div
                className={`chat-bubble ${
                  msg.type === "me"
                    ? "user-chat"
                    : msg.type === "ai"
                    ? "ai-chat"
                    : "other-chat"
                }`}
              >
                {msg.text}
              </div>

            </div>

          </div>

        ))}

        <div ref={chatEndRef}></div>

      </div>


      {/* =========================
          AI 진행자 버튼
      ========================= */}

      <div className="ai-button-wrap">

        <button
          className="ai-request-btn"
          onClick={requestAI}
        >
          ✨ AI 진행자에게 질문하기
        </button>

      </div>


      {/* =========================
          메시지 입력
      ========================= */}

      <div className="meeting-input-wrap">

        <input
          value={input}
          onChange={(e) =>
            setInput(e.target.value)
          }
          placeholder="생각을 입력해보세요"
          onKeyDown={(e) => {

            if (e.key === "Enter") {
              sendMessage();
            }

          }}
        />

        <button
          onClick={sendMessage}
        >
          전송
        </button>

      </div>


      {/* =========================
          AI 버튼 CSS
      ========================= */}

      <style>{`

        .ai-button-wrap {
          width: 100%;
          box-sizing: border-box;

          padding: 6px 12px 8px;

          display: flex;
          justify-content: center;

          background: #ffffff;
        }


        .ai-request-btn {
          width: 100%;
          max-width: 390px;

          height: 40px;

          border: none;
          border-radius: 14px;

          background: #eef7da;
          color: #6a8c2f;

          font-size: 13px;
          font-weight: 700;

          cursor: pointer;

          transition:
            background 0.15s ease,
            transform 0.15s ease;
        }


        .ai-request-btn:hover {
          background: #e4f1c8;
        }


        .ai-request-btn:active {
          transform: scale(0.98);
        }

      `}</style>

    </div>
  );
}

export default MeetingRoom;
